//! T32 cutover follow-up (t3309): populated outbox and stuck state in `dunks.json`.
//!
//! The fixtures under `tests/fixtures/dunks/` are SANITIZED populated state files written by the
//! Python implementation (`dunk_core.Flock._save()`, regenerated by
//! `make_python_populated_fixtures.py`). They hold queued outbox rows with holds, a notice and hold
//! signatures; stuck candidates recorded by the real Python methods; the stuck tracker's records and
//! spent ledger in the daemon's insertion order (not sorted by pane); and a non-default stuck config.
//!
//! Each file gets two checks:
//! - `*_keeps_every_python_value`: restore the Python file, save it, and every value the Python file
//!   holds is still there. This is the state-preservation half of the cutover requirement.
//! - `*_round_trips_byte_identical`: the saved bytes equal the Python bytes. This is the byte-identity
//!   half that owner decision B (t800) parked as this follow-up under t1605.

use super::{status_runtime::StatusState, Flock};
use crate::config::Env;
use serde_json::Value;

const PYTHON_OUTBOX: &[u8] =
    include_bytes!("../../tests/fixtures/dunks/python-written-populated-outbox.json");
const PYTHON_STUCK: &[u8] =
    include_bytes!("../../tests/fixtures/dunks/python-written-populated-stuck.json");

fn flock(dir: &std::path::Path) -> Flock {
    Flock::new(dir.join("launches.json"), dir.join("lanes.json"), true)
}

/// Restore a Python-written file into a fresh Flock attached to a state file, save it back, and
/// return the bytes the Rust daemon wrote.
fn restore_then_save(python: &[u8]) -> Vec<u8> {
    let dir = tempfile::tempdir().unwrap();
    let executable = dir.path().join("daemon");
    std::fs::write(&executable, b"fixture").unwrap();
    let state_path = dir.path().join("dunks.json");
    std::fs::write(&state_path, python).unwrap();
    let payload: Value = serde_json::from_slice(python).unwrap();

    let flock = flock(dir.path());
    flock
        .attach_status_state(StatusState::at_start(
            "test",
            &state_path,
            executable,
            Env::default(),
        ))
        .unwrap();
    flock.restore_snapshot(&payload);
    flock.save().unwrap();
    std::fs::read(&state_path).unwrap()
}

/// Every value the Python file holds is present in the Rust file with the same value. Rust may add
/// keys of its own, arrays keep their length and order, and a key the Python file does not hold a
/// value for may be absent (a missing key and a `null` read back the same).
fn assert_python_values_kept(path: &str, python: &Value, rust: &Value) {
    match (python, rust) {
        (Value::Object(expected), Value::Object(actual)) => {
            let absent = Value::Null;
            for (key, value) in expected {
                let actual_value = actual.get(key).unwrap_or(&absent);
                assert_python_values_kept(&format!("{path}.{key}"), value, actual_value);
            }
        }
        (Value::Array(expected), Value::Array(actual)) => {
            assert_eq!(expected.len(), actual.len(), "{path}: number of rows");
            for (index, (value, actual_value)) in expected.iter().zip(actual).enumerate() {
                assert_python_values_kept(&format!("{path}[{index}]"), value, actual_value);
            }
        }
        _ => assert_eq!(python, rust, "{path}: a value the Python file holds"),
    }
}

/// Byte identity with the Python writer. On failure, name the first differing byte and show the
/// bytes on each side around it.
fn assert_byte_identical(python: &[u8], rust: &[u8]) {
    if python == rust {
        return;
    }
    let first = python
        .iter()
        .zip(rust)
        .position(|(expected, actual)| expected != actual)
        .unwrap_or(python.len().min(rust.len()));
    let window = |bytes: &[u8]| {
        let start = first.saturating_sub(80).min(bytes.len());
        let end = (first + 80).min(bytes.len());
        String::from_utf8_lossy(&bytes[start..end]).into_owned()
    };
    panic!(
        "a Rust save must match the Python-written file byte for byte: first difference at byte \
         {first} (python {} bytes, rust {} bytes)\n--- python around it ---\n{}\n--- rust around it \
         ---\n{}",
        python.len(),
        rust.len(),
        window(python),
        window(rust)
    );
}

#[test]
fn populated_outbox_keeps_every_python_value() {
    let python: Value = serde_json::from_slice(PYTHON_OUTBOX).unwrap();
    let rust: Value = serde_json::from_slice(&restore_then_save(PYTHON_OUTBOX)).unwrap();
    assert_python_values_kept("$", &python, &rust);
}

#[test]
fn populated_outbox_round_trips_byte_identical() {
    assert_byte_identical(PYTHON_OUTBOX, &restore_then_save(PYTHON_OUTBOX));
}

#[test]
fn populated_stuck_state_keeps_every_python_value() {
    let python: Value = serde_json::from_slice(PYTHON_STUCK).unwrap();
    let rust: Value = serde_json::from_slice(&restore_then_save(PYTHON_STUCK)).unwrap();
    assert_python_values_kept("$", &python, &rust);
}

#[test]
fn populated_stuck_state_round_trips_byte_identical() {
    assert_byte_identical(PYTHON_STUCK, &restore_then_save(PYTHON_STUCK));
}
